import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {coverage,policy,architecture,regionalPages,groupsFor,assertRegionalInput,isUnboundTemplate} from '../src/lib/regional-runtime.mjs';
import {validateDefinition,regionalMetadata} from '../src/lib/regions.mjs';
import {validateHubMetadata} from '../scripts/qa_graph.mjs';
const read=name=>JSON.parse(fs.readFileSync(new URL(`../src/data/${name}.json`,import.meta.url),'utf8'));
const c={schemaVersion:2,siteKey:'template-only',scopeKey:'',unitBasis:'legal-dong-plus-eup-myeon',countIsPageQuota:false,verifiedAt:'',sourceBasisDate:'',officialSourceUrls:[],membershipSourceSha256:'',districts:[],units:[],administrativeCrosswalk:[],representatives:[]};
const p={schemaVersion:1,siteKey:'template-only',scopeKey:'',enabled:false,officialHosts:[],unitTypes:[],rulesRevision:'',definitionFile:'src/data/region-coverage.json',state:'unbound-template',membershipSourceSha256:'',visualBindings:[]};
const a={siteKey:'template-only',pages:[]},m={siteKey:'template-only',pages:[],snapshotLedger:{}};
test('stored hub policy matches runtime thresholds, including empty and paused previews',()=>{
 for(const count of [0,1,2,3,4,5,53]){
  const pages=Array.from({length:count},()=>({category:'regions'}));
  const hub={category:'regions',url:'/regions/',children:count,indexable:count>=3,menuVisible:count>=5};
  assert.doesNotThrow(()=>validateHubMetadata(pages,{hubs:[hub]}));
  for(const field of ['indexable','menuVisible'])assert.throws(()=>validateHubMetadata(pages,{hubs:[{...hub,[field]:!hub[field]}]}),/Stale hub index\/menu policy/);
  assert.throws(()=>validateHubMetadata(pages,{hubs:[{...hub,children:count+1}]}),/Stale hub child count/);
 }
});
test('actual runtime input matches its frozen manifest without template-only assumptions',()=>{
 const pages=read('pages');
 assert.deepEqual(assertRegionalInput(pages),regionalPages);
 assert.equal(Array.isArray(groupsFor(pages)),true);
});
test('unbound template has no customers, geography, snapshots or approvals',()=>{
 if(coverage.siteKey!=='template-only'){assert.equal(isUnboundTemplate(coverage,policy,architecture,read('publish-manifest')),false);return;}
 const manifest=read('publish-manifest');
 assert.equal(isUnboundTemplate(coverage,policy,architecture,manifest),true);
 assert.deepEqual(read('pages'),[]);assert.deepEqual(manifest.snapshotLedger,{});
 for(const field of ['districts','units','administrativeCrosswalk','representatives'])assert.deepEqual(coverage[field],[]);
 assert.equal(policy.enabled,false);assert.deepEqual(policy.visualBindings,[]);
 assert.deepEqual(regionalPages,[]);assert.deepEqual(groupsFor([]),[]);assert.deepEqual(assertRegionalInput([]),[]);
 assert.deepEqual(architecture.hubs.map(h=>h.category),['funeral','business','school','event','gift','order','regions']);
 assert.ok(architecture.hubs.every(h=>h.children===0&&!h.indexable&&!h.menuVisible));
});
test('unbound sentinel is exact and cannot silently accept claims or content',()=>{
 for(const [kind,field,value] of [['c','scopeKey','scope'],['c','verifiedAt','2026-01-01'],['c','extra',true],['p','enabled',true],['p','visualBindings',[{}]],['p','state','approved']]){
  const cc=structuredClone(c),pp=structuredClone(p);(kind==='c'?cc:pp)[field]=value;
  assert.throws(()=>isUnboundTemplate(cc,pp,a,m),/Invalid unbound/);
 }
 assert.equal(isUnboundTemplate(c,p,a,m),true);
 assert.throws(()=>isUnboundTemplate(c,p,{...a,pages:[{}]},m),/Invalid unbound/);
 assert.throws(()=>isUnboundTemplate(c,p,a,{...m,pages:[{}]}),/Invalid unbound/);
 assert.throws(()=>validateDefinition(c,p),/opt-in mismatch/);
 assert.throws(()=>regionalMetadata(c,p,read('products'),'missing'),/reviewed binding/);
 if(coverage.siteKey==='template-only'){assert.throws(()=>groupsFor([{}]),/customer pages/);assert.throws(()=>assertRegionalInput([{}]),/customer pages/);}
});

tests/social-image.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {productSocialImage} from '../src/lib/social-image.mjs';
const products=JSON.parse(fs.readFileSync(new URL('../src/data/products.json',import.meta.url)));
const provenance=JSON.parse(fs.readFileSync(new URL('../src/data/social-image-provenance.json',import.meta.url)));
test('every source-pinned product maps to its real unchanged image bytes and generic origin',()=>{
  for(const product of products){
    const image=productSocialImage(product,provenance,'https://example.invalid','검증 브랜드');
    const proof=provenance.products.find(row=>row.key===product.key);
    const bytes=fs.readFileSync(new URL('../public'+product.img,import.meta.url));
    assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),proof.image.sha256);
    assert.equal(image.url,'https://example.invalid'+product.img);
    assert.equal(image.alt,'검증 브랜드 '+product.name);
    assert.ok(image.width>0&&image.height>0);
    assert.ok(image.type.startsWith('image/'));
  }
});
test('different region/brand uses same verified photo without inventing a local image',()=>{
  const image=productSocialImage(products[0],provenance,'https://region.example.invalid','다른 브랜드');
  assert.equal(image.alt,'다른 브랜드 '+products[0].name);
  assert.match(image.url,/^https:\/\/region\.example\.invalid\//);
});
test('unverified product, changed SKU binding, external image and invalid origin fail closed',()=>{
  for(const change of [{assetType:'editorial_illustration'},{sourceLevel:'unknown'},{name:'다른 상품'},
      {sourceUrl:'https://other.invalid/product'},{orderUrl:'https://other.invalid/buy'},
      {img:'https://other.invalid/photo.jpg'},{img:'/images/products/../other.jpg'},{key:'unknown'}])
    assert.throws(()=>productSocialImage({...products[0],...change},provenance,'https://example.invalid','브랜드'));
  for(const origin of ['http://example.invalid','https://user:password@example.invalid'])
    assert.throws(()=>productSocialImage(products[0],provenance,origin,'브랜드'));
  const broken=structuredClone(provenance);broken.products[0].image.dimensions=[0,500];
  assert.throws(()=>productSocialImage(products[0],broken,'https://example.invalid','브랜드'));
});

tests/sources.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {pageSources,sourceTypeLabels} from '../src/lib/sources.mjs';
const pages=JSON.parse(fs.readFileSync(new URL('../src/data/pages.json',import.meta.url)));
const source={name:'검토된 시설 출처',url:'https://example.org/path?a=1&b=2',type:'facility',verifiedAt:'2026-10-02'};
test('every frozen source is retained in reviewed order without mutation',()=>{
  const before=JSON.stringify(pages);
  for(const page of pages){
    assert.ok(page.sources.length>0);
    assert.deepEqual(pageSources(page),page.sources);
    assert.equal(pageSources(page)[0],page.sources[0]);
  }
  assert.equal(JSON.stringify(pages),before);
});
test('legacy primary-only page remains supported without inventing sources',()=>{
  assert.deepEqual(pageSources({source}),[source]);
  assert.deepEqual(pageSources({}),[]);
  assert.deepEqual(pageSources({sources:[],source}),[]);
  assert.deepEqual(pageSources({sources:[source],source:{...source,name:'obsolete'}}),[source]);
});
test('URLs, queries, duplicate entries, and trailing slash are not rewritten',()=>{
  const sources=[source,source,{...source,url:'https://fwith.co.kr/'},{...source,url:'https://fwith.co.kr'}];
  assert.deepEqual(pageSources({sources}),sources);
});
test('unsafe or malformed URLs fail closed instead of hiding a source',()=>{
  for(const url of ['http://example.org','javascript:alert(1)','data:text/html,test','//example.org','https://user:secret@example.org','https://example.org/\npath','https://example.org/a b','https://example.org\\evil','invalid']){
    assert.throws(()=>pageSources({sources:[source,{...source,url}]}));
  }
});
test('invalid reviewed metadata and non-array sources fail closed',()=>{
  for(const change of [{name:''},{type:'unverified'},{verifiedAt:''},{verifiedAt:'tomorrow'}])
    assert.throws(()=>pageSources({sources:[{...source,...change}]}));
  assert.throws(()=>pageSources({sources:{}}));
  assert.deepEqual(Object.keys(sourceTypeLabels),['official','business','facility','education','professional','reference']);
});
test('renderer uses escaped expressions, accessible source links and existing stacked cards',()=>{
  const template=fs.readFileSync(new URL('../src/pages/[category]/[slug].astro',import.meta.url),'utf8');
  const block=template.slice(template.indexOf('{sources.map'),template.indexOf('\n{!page.contentMarkdown && page.faq'));
  assert.match(block,/\{source.name\}/);assert.match(block,/href=\{source.url\}/);
  assert.match(block,/datetime=\{source.verifiedAt\}/);assert.match(block,/data-source-type=\{source.type\}/);
  assert.match(block,/aria-label=/);assert.doesNotMatch(block,/set:html|page\.source\./);
  assert.match(block,/class="source-card"/);
  assert.match(block,/출처 확인 →/);assert.doesNotMatch(block,/공식정보 확인|아래 공식 출처|시설 안내|상품과 주문 안내/);
});

